create table if not exists public.products (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, name text not null, description text default '', price numeric(10,2) not null default 0, stock integer not null default 0, variants jsonb not null default '[]'::jsonb, image_url text default '', available boolean default true, created_at timestamptz default now());
alter table public.products add column if not exists variants jsonb not null default '[]'::jsonb;
create table if not exists public.orders (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, order_number text, customer_email text, customer_address text, shipping_method text, shipping_price numeric(10,2) default 0, total numeric(10,2) default 0, status text default 'Nuovo', created_at timestamptz default now());
alter table public.orders add column if not exists customer_name text;
alter table public.orders add column if not exists items jsonb not null default '[]'::jsonb;
alter table public.orders add column if not exists payment_method text default 'Pagamento manuale';
create table if not exists public.coupons (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, name text not null, code text not null, percent_off numeric(5,2) not null default 0, active boolean default true, created_at timestamptz default now(), unique(owner_id,code));
create table if not exists public.store_settings (owner_id uuid primary key references auth.users(id) on delete cascade, store_name text default 'Il Gatto di Cruci', contact_email text, phone text, shipping_address text, updated_at timestamptz default now());
create table if not exists public.sale_links (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, title text not null, description text default '', slug text not null unique default encode(gen_random_bytes(6), 'hex'), visits integer not null default 0, created_at timestamptz default now());
create table if not exists public.sale_link_products (link_id uuid not null references public.sale_links(id) on delete cascade, product_id uuid not null references public.products(id) on delete cascade, primary key(link_id, product_id));
create table if not exists public.sale_link_coupons (link_id uuid not null references public.sale_links(id) on delete cascade, coupon_id uuid not null references public.coupons(id) on delete cascade, primary key(link_id, coupon_id));
alter table public.products enable row level security; alter table public.orders enable row level security; alter table public.coupons enable row level security; alter table public.store_settings enable row level security;
alter table public.sale_links enable row level security; alter table public.sale_link_products enable row level security; alter table public.sale_link_coupons enable row level security;
create policy "owners manage products" on public.products for all using (owner_id=auth.uid()) with check (owner_id=auth.uid());
create policy "owners manage orders" on public.orders for all using (owner_id=auth.uid()) with check (owner_id=auth.uid());
create policy "owners manage coupons" on public.coupons for all using (owner_id=auth.uid()) with check (owner_id=auth.uid());
create policy "owners manage settings" on public.store_settings for all using (owner_id=auth.uid()) with check (owner_id=auth.uid());
create policy "owners manage sale links" on public.sale_links for all using (owner_id=auth.uid()) with check (owner_id=auth.uid());
create policy "owners manage sale link products" on public.sale_link_products for all using (exists (select 1 from public.sale_links where id=link_id and owner_id=auth.uid())) with check (exists (select 1 from public.sale_links where id=link_id and owner_id=auth.uid()));
create policy "owners manage sale link coupons" on public.sale_link_coupons for all using (exists (select 1 from public.sale_links where id=link_id and owner_id=auth.uid())) with check (exists (select 1 from public.sale_links where id=link_id and owner_id=auth.uid()));
